package am.ik.yavi.fn;

import am.ik.yavi.jsr305.Nullable;

/**
 * A function that takes 12 arguments and produces a result.
 *
 * <p>
 * This is the 12-argument variant of {@link java.util.function.Function}, used to apply a
 * function to the values of combined validation results. Every argument is annotated
 * {@link am.ik.yavi.jsr305.Nullable}, so implementations must accept {@code null}
 * arguments.
 *
 * <p>
 * Generated by <a href=
 * "https://github.com/making/yavi/blob/develop/scripts/generate-function.sh">generate-function.sh</a>.
 *
 * @param <T1> the type of argument 1
 * @param <T2> the type of argument 2
 * @param <T3> the type of argument 3
 * @param <T4> the type of argument 4
 * @param <T5> the type of argument 5
 * @param <T6> the type of argument 6
 * @param <T7> the type of argument 7
 * @param <T8> the type of argument 8
 * @param <T9> the type of argument 9
 * @param <T10> the type of argument 10
 * @param <T11> the type of argument 11
 * @param <T12> the type of argument 12
 * @param <R> the type of the result
 * @since 0.6.0
 */
@FunctionalInterface
public interface Function12<T1, T2, T3, T4, T5, T6, T7, T8, T9, T10, T11, T12, R> {

	/**
	 * Applies this function to the given arguments.
	 * @param t1 argument 1, possibly {@code null}
	 * @param t2 argument 2, possibly {@code null}
	 * @param t3 argument 3, possibly {@code null}
	 * @param t4 argument 4, possibly {@code null}
	 * @param t5 argument 5, possibly {@code null}
	 * @param t6 argument 6, possibly {@code null}
	 * @param t7 argument 7, possibly {@code null}
	 * @param t8 argument 8, possibly {@code null}
	 * @param t9 argument 9, possibly {@code null}
	 * @param t10 argument 10, possibly {@code null}
	 * @param t11 argument 11, possibly {@code null}
	 * @param t12 argument 12, possibly {@code null}
	 * @return the function result
	 */
	R apply(@Nullable T1 t1, @Nullable T2 t2, @Nullable T3 t3, @Nullable T4 t4, @Nullable T5 t5, @Nullable T6 t6,
			@Nullable T7 t7, @Nullable T8 t8, @Nullable T9 t9, @Nullable T10 t10, @Nullable T11 t11, @Nullable T12 t12);

}
